export function csvParserSettings(options) {
  const {
    delimiter = ",",
    quote = "\"",
    escape = quote,
    encoding = "utf-8",
    trim,
    ltrim,
    rtrim,
    comment,
    headers,
    objectMode = true,
    renameHeaders,
    ignoreEmpty,
    maxRows = 0,
    skipRows = 0,
    skipLines = 0,
  } = options ?? {};
  if (delimiter?.length !== 1) throw failure("UNSUPPORTED_OPTIONS", "CSV delimiters, quotes and escapes must be single characters");
  if (quote && quote.length !== 1) throw failure("UNSUPPORTED_OPTIONS", "CSV delimiters, quotes and escapes must be single characters");
  if (escape && escape.length !== 1) throw failure("UNSUPPORTED_OPTIONS", "CSV delimiters, quotes and escapes must be single characters");
  if (headers) throw failure("UNSUPPORTED_OPTIONS", "ExcelJS CSV input requires array records");
  if (!objectMode) throw failure("UNSUPPORTED_OPTIONS", "ExcelJS CSV input requires array records");
  if (renameHeaders) throw failure("UNSUPPORTED_OPTIONS", "ExcelJS CSV input requires array records");
  return { delimiter, quote, escape, encoding, trim, ltrim, rtrim, comment, headers, objectMode, renameHeaders, ignoreEmpty, maxRows, skipRows, skipLines };
}

