export function workbookLoadSettings(options) {
  const settings = {};
  collect(options, ["base64","maxRows","maxCols","ignoreNodes"], settings);
  optionsMatch(options, settings);
  if (settings.base64 !== undefined && typeof settings.base64 !== 'boolean') {
    throw failure('UNSUPPORTED_OPTIONS', "Expected boolean base64 and nonnegative integer grid limits");
  }
  if (settings.maxRows !== undefined && (!Number.isInteger(settings.maxRows) || settings.maxRows < 0 || settings.maxRows > 0xffffffff)) {
    throw failure('UNSUPPORTED_OPTIONS', "Expected boolean base64 and nonnegative integer grid limits");
  }
  if (settings.maxCols !== undefined && (!Number.isInteger(settings.maxCols) || settings.maxCols < 0 || settings.maxCols > 0xffffffff)) {
    throw failure('UNSUPPORTED_OPTIONS', "Expected boolean base64 and nonnegative integer grid limits");
  }
  if (settings.ignoreNodes !== undefined &&
      (!Array.isArray(settings.ignoreNodes) || Array.from(settings.ignoreNodes).some(item => !["autoFilter","cols","conditionalFormatting","dataValidations","dimension","drawing","extLst","headerFooter","hyperlinks","mergeCells","pageMargins","pageSetup","picture","printOptions","rowBreaks","sheetFormatPr","sheetPr","sheetProtection","sheetViews","tableParts"].includes(item)))) {
    throw failure('UNSUPPORTED_OPTIONS', "Unsupported worksheet node in ignoreNodes");
  }
  if (settings.maxRows === undefined) settings.maxRows = 0;
  if (settings.maxCols === undefined) settings.maxCols = 0;
  if (settings.ignoreNodes === undefined) settings.ignoreNodes = [];
  return settings;
}

